export interface ProviderPayslip {
  employee_ref: string;
  period_start: number;
  period_end: number;
  pay_date: number;
  gross_cents: string;
  net_cents: string;
  currency: string;
  deductions: { code: string; amount_cents: string }[];
}

export interface ProviderPage {
  payslips: ProviderPayslip[];
  next_cursor: string | null;
}

export class PayrollProviderClient {
  constructor(private readonly baseUrl: string, private readonly apiKey: string) {}

  async fetchPayslips(runId: string, cursor: string | null): Promise<ProviderPage> {
    const url = new URL(`/v2/runs/${encodeURIComponent(runId)}/payslips`, this.baseUrl);
    if (cursor) url.searchParams.set("cursor", cursor);
    const res = await fetch(url, {
      headers: { authorization: `Bearer ${this.apiKey}`, accept: "application/json" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) throw new Error(`provider responded ${res.status} for run ${runId}`);
    return (await res.json()) as ProviderPage;
  }
}

import { ProviderPayslip } from "./providerClient";

export interface Payslip {
  employeeId: string;
  periodStart: Date;
  periodEnd: Date;
  payDate: Date;
  grossCents: bigint;
  netCents: bigint;
  currency: string;
  deductions: Map<string, bigint>;
}

function toCents(field: string, value: string): bigint {
  if (!/^-?\d+$/.test(value)) throw new Error(`${field} is not an integer string: ${value}`);
  return BigInt(value);
}

function fromEpochSeconds(field: string, value: number): Date {
  if (!Number.isInteger(value) || value <= 0) throw new Error(`${field} is not a valid epoch`);
  return new Date(value * 1000);
}

export function mapPayslip(p: ProviderPayslip): Payslip {
  const deductions = new Map<string, bigint>();
  for (const d of p.deductions ?? []) {
    const prev = deductions.get(d.code) ?? 0n;
    deductions.set(d.code, prev + toCents(`deduction ${d.code}`, d.amount_cents));
  }
  const gross = toCents("gross_cents", p.gross_cents);
  const net = toCents("net_cents", p.net_cents);
  const totalDeductions = [...deductions.values()].reduce((a, b) => a + b, 0n);
  if (gross - totalDeductions !== net) {
    throw new Error(`payslip for ${p.employee_ref} does not balance`);
  }
  return {
    employeeId: p.employee_ref,
    periodStart: fromEpochSeconds("period_start", p.period_start),
    periodEnd: fromEpochSeconds("period_end", p.period_end),
    payDate: new Date(p.pay_date),
    grossCents: gross,
    netCents: net,
    currency: p.currency.toUpperCase(),
    deductions,
  };
}

import { PayrollProviderClient } from "./providerClient";
import { mapPayslip, Payslip } from "./payslipMapper";

export interface PayslipRepo {
  upsert(runId: string, slip: Payslip): Promise<void>;
}

export interface ImportSummary {
  imported: number;
  rejected: { employeeRef: string; reason: string }[];
}

export async function importRun(
  client: PayrollProviderClient,
  repo: PayslipRepo,
  runId: string,
): Promise<ImportSummary> {
  const summary: ImportSummary = { imported: 0, rejected: [] };
  let cursor: string | null = null;
  do {
    const page = await client.fetchPayslips(runId, cursor);
    for (const raw of page.payslips) {
      let slip: Payslip;
      try {
        slip = mapPayslip(raw);
      } catch (err) {
        summary.rejected.push({ employeeRef: raw.employee_ref, reason: (err as Error).message });
        continue;
      }
      await repo.upsert(runId, slip);
      summary.imported++;
    }
    cursor = page.next_cursor;
  } while (cursor);
  return summary;
}
